// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
import { evolvePath } from "@remotion/paths";

// Module-level font loading — handles delayRender/continueRender internally
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type SprintVelocityProps = Record<string, any>;

const SprintVelocity: React.FC<SprintVelocityProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  graphLabel = "SPRINT VELOCITY",
  backgroundText = "TEAM TRUST",
  lineColor = "#000000",
  textColor = "#000000",
  backgroundTextColor = "#000000",
  lineWidth = 6,
  jaggedness = 0.2,
  showAxes = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Safe timing bounds calculation
  const totalFrames = durationInSeconds * fps;
  const startFrame = 15;
  const endFrame = Math.max(startFrame + 1, totalFrames - 30); // Ensures strictly increasing monotonic range

  // Main evolution progress for the graph drawing
  const drawProgress = interpolate(frame, [startFrame, endFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });

  // Calculate jagged path points deterministically
  const points = useMemo(() => {
    return Array.from({ length: 12 }).map((_, i) => {
      const x = width * 0.1 + width * 0.8 * (i / 11);
      const progress = i / 11;

      // Base line logic: drop from 20% to 80% visually
      const baseY = height * 0.2 + height * 0.6 * progress;

      // Introduce random deterministic jagged spikes
      let jagg = 0;
      if (i !== 0 && i !== 11) {
        jagg = (random(`jagg-${i}`) - 0.5) * height * jaggedness * 2;
      }

      // Constrain points to safe vertical visual zones (avoids spilling out of graph area)
      const boundedY = Math.max(height * 0.15, Math.min(height * 0.85, baseY + jagg));
      return [x, boundedY];
    });
  }, [width, height, jaggedness]);

  // Construct standard SVG path data
  const pathD = useMemo(() => {
    if (points.length === 0) return "";
    return (
      `M ${points[0][0]} ${points[0][1]} ` +
      points.slice(1).map((p) => `L ${p[0]} ${p[1]}`).join(" ")
    );
  }, [points]);

  // Use Remotion paths capability to get evolving dash parameters
  const evolution = evolvePath(drawProgress, pathD);

  // Background text fades and blurs synchronously with the graph dropping
  const textOpacity = interpolate(drawProgress, [0, 1], [0.15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const textBlur = interpolate(drawProgress, [0, 1], [4, 24], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Fade in title right at the start
  const labelOpacity = interpolate(frame, [0, startFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGroteskFamily,
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Background Overlay Text */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 1,
        }}
      >
        <div
          style={{
            fontSize: width * 0.12,
            fontWeight: 900,
            color: backgroundTextColor,
            opacity: textOpacity,
            filter: `blur(${textBlur}px)`,
            whiteSpace: "nowrap",
          }}
        >
          {backgroundText}
        </div>
      </div>

      {/* Minimalist Grid / Axes */}
      {showAxes && (
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", zIndex: 0, opacity: 0.15 }}
        >
          <line
            x1={width * 0.1}
            y1={height * 0.9}
            x2={width * 0.9}
            y2={height * 0.9}
            stroke={textColor}
            strokeWidth={2}
          />
          <line
            x1={width * 0.1}
            y1={height * 0.1}
            x2={width * 0.1}
            y2={height * 0.9}
            stroke={textColor}
            strokeWidth={2}
          />
        </svg>
      )}

      {/* Top Left Title Label */}
      <div
        style={{
          position: "absolute",
          left: width * 0.1,
          top: height * 0.08,
          fontSize: Math.max(24, height * 0.04),
          fontWeight: "bold",
          color: textColor,
          zIndex: 3,
          letterSpacing: "0.05em",
          opacity: labelOpacity,
        }}
      >
        {graphLabel}
      </div>

      {/* Jagged Graph Lines & Node Circles */}
      <svg width={width} height={height} style={{ position: "absolute", zIndex: 2 }}>
        <path
          d={pathD}
          fill="none"
          stroke={lineColor}
          strokeWidth={lineWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
        />
        {points.map((p, i) => {
          // Trigger individual node scaling based on when the line hits its index
          const pointAppearanceTime = i / (points.length - 1);
          const radius = interpolate(
            drawProgress,
            [pointAppearanceTime, pointAppearanceTime + 0.05],
            [0, lineWidth * 1.5],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          return (
            <circle
              key={i}
              cx={p[0]}
              cy={p[1]}
              r={radius}
              fill={backgroundColor}
              stroke={lineColor}
              strokeWidth={lineWidth * 0.5}
            />
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default SprintVelocity;